      "against": [
        { "text": "급성 단일 신경근 방사통·SLR 강양성·젊은 연령이면 디스크 쪽으로 가중", "basis": "history" },
        { "text": "하지 맥박 감소·피부 변화 동반 시 혈관성 파행(감별 필요)", "basis": "history" }
