        { "text": "안정 시·전굴 시 완화가 뚜렷하면 신경인성 파행 쪽으로 가중", "basis": "history" }
      ]
    },
    {
      "name": "척추 감염·종양·골절(비기계적 원인)",
      "icd10": "M46.4 / C79.5 / S32.0",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "발열·야간/휴식 통증·암 병력·스테로이드/항응고제 노출 — 현재 모두 미확인", "basis": "history" }
      ],
      "against": [
        { "text": "기계적 유발 패턴(자세·부하)으로만 통증이 조절되면 기계적 원인 쪽으로 가중", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "안장부(회음·내측 대퇴) 감각 저하, 배뇨·배변 조절 이상, 양하지 진행성 근력 저하가 있는가? (있다면 즉시 응급 평가로 전환)"
  ],
  "suggested_tests": [
    { "name": "SLR(Straight Leg Raise)/Lasegue 및 교차 SLR, Bragard 보강", "purpose": "신경근 압박(L4–S1) 시사 소견 확보", "urgency": "now", "basis": "guideline" },
    { "name": "근력 MRC 0–5 등급: 고관절 굴곡·신전(L2–L3), 무릎 신전(L4), 발목 배굴(L4–L5), 엄지 신전(EHL, L5), 발목 저굴·발가락 굴곡(S1)", "purpose": "침범 신경근 수준 국소화 및 기준선 기록", "urgency": "now", "basis": "guideline" },
    { "name": "감각 검사: 피부절 지도에 따른 핀프릭/가벼운 접촉 — L4 내측 하퇴, L5 하퇴 외측·엄지, S1 하퇴 후면·발바닥", "purpose": "피부절 국소화", "urgency": "now", "basis": "guideline" },
    { "name": "안장부 감각(S2–S4) 및 항문 괄약근 긴장도/자발 수축", "purpose": "마미증후군 배제 — 양성 시 즉시 응급", "urgency": "now", "basis": "guideline" },
    { "name": "직립 신전 유발 검사(stoop test, bicycle test 등) 및 보행 유발 검사", "purpose": "협착 시사 파행 패턴 확인", "urgency": "24h", "basis": "guideline" },
    { "name": "양측 하지 맥박·ABI(필요 시)", "purpose": "혈관성 파행 감별", "urgency": "24h", "basis": "guideline" },
    { "name": "하지 직거상 검사와 함께 심부건반사(슬개건 L4, 아킬레스건 S1)", "purpose": "침범 수준 보강", "urgency": "now", "basis": "guideline" },
    { "name": "영상: MRI 요추(응급/조기 적응 여부는 대면 의사 판단) — 진행성 결손·마미·종양/감염 의심 시 즉시", "purpose": "신경 압박·감염·종양 감별", "urgency": "24h", "basis": "guideline" }
